CREATE TABLE vehicle_daily_statistics (vehicle_id BIGINT NOT NULL, day_utc DATE NOT NULL, distance_km DECIMAL(12,3) NOT NULL DEFAULT 0, driving_kwh DECIMAL(12,3) NOT NULL DEFAULT 0, charging_kwh DECIMAL(12,3) NOT NULL DEFAULT 0, charging_cost DECIMAL(12,2) NOT NULL DEFAULT 0, trip_count INT NOT NULL DEFAULT 0, charge_count INT NOT NULL DEFAULT 0, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(vehicle_id,day_utc), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
